require 'set'

class Filler
  Attempt = Struct.new(:minimum, :budget, :outcome, :nodes, :backtracks, :prunes,
                       :dead_ends, :max_depth, :failures, :trace, :sequence, :state,
                       keyword_init: true)

  def initialize(index, slots, initial, minimum, budget)
    @index = index
    @slots = slots
    @state = initial.copy
    @minimum = minimum
    @budget = budget
    @used = Set.new(@state.assigned.compact)
    @nodes = @backtracks = @prunes = @dead_ends = @max_depth = 0
    @sequence = []
    @best = @state.copy
    @failures = Array.new(slots.length, 0)
    @trace = []
  end

  def run
    result = search
    outcome = { complete: 'filled', fail: 'unfillable', abort: 'budget' }.fetch(result)
    final_state = result == :complete ? @state.copy : @best
    Attempt.new(minimum: @minimum, budget: @budget, outcome: outcome, nodes: @nodes,
                backtracks: @backtracks, prunes: @prunes, dead_ends: @dead_ends,
                max_depth: @max_depth, failures: @failures, trace: @trace,
                sequence: @sequence.dup, state: final_state)
  end

  private

  def candidates(slot)
    @index.candidates(@state.pattern(slot), @minimum, @used)
  end

  def search
    chosen = nil
    choices = nil
    @slots.each do |slot|
      next if @state.assigned[slot.id]

      available = candidates(slot)
      if chosen.nil? || available.length < choices.length
        chosen = slot
        choices = available
      end
    end
    return :complete if chosen.nil?

    if choices.empty?
      @dead_ends += 1
      @failures[chosen.id] += 1
      return :fail
    end
    choices.each do |word|
      return :abort if @nodes == @budget

      @nodes += 1
      @state.assigned[chosen.id] = word
      @used.add(word)
      changed = []
      chosen.cells.each_with_index do |cell, position|
        next unless @state.cells[cell] == '.'

        changed << cell
        @state.cells[cell] = word[position]
      end
      @sequence << chosen.id
      wiped = chosen.crossings.find do |id|
        @state.assigned[id].nil? && candidates(@slots[id]).empty?
      end
      @trace << "#{chosen.label}=#{word}#{wiped.nil? ? '' : '!'}" if @nodes <= 10
      if wiped
        @prunes += 1
        @failures[wiped] += 1
        result = :fail
      else
        if @sequence.length > @max_depth
          @max_depth = @sequence.length
          @best = @state.copy
        end
        result = search
      end
      return result if result == :complete || result == :abort

      @state.assigned[chosen.id] = nil
      @used.delete(word)
      changed.each { |cell| @state.cells[cell] = '.' }
      @sequence.pop
      @backtracks += 1
    end
    :fail
  end
end

class WordIndex
  attr_reader :scores, :ranked, :by_length

  def self.valid_word?(word)
    /\A[A-Z]{3,15}\z/.match?(word)
  end

  def self.valid_integer?(text, minimum, maximum)
    /\A[1-9][0-9]*\z/.match?(text) && text.to_i.between?(minimum, maximum)
  end

  def self.word_line_error(line)
    return 'bad format' unless line.count(' ') == 1

    word, _, score = line.partition(' ')
    return 'bad word' unless valid_word?(word)
    return 'bad score' unless valid_integer?(score, 1, 100)

    nil
  end

  def self.clue_line_error(line)
    return 'bad format' unless line.count('|') == 1

    word, _, clue = line.partition('|')
    return 'bad word' unless valid_word?(word)
    return 'bad clue' unless clue.length.between?(1, 60) &&
                             !clue.start_with?(' ') && !clue.end_with?(' ')

    nil
  end

  def initialize(scores)
    @scores = scores
    @ranked = scores.keys.sort_by { |word| [-scores.fetch(word), word] }
    @by_length = Hash.new { |hash, length| hash[length] = [] }
    @by_position = Hash.new { |hash, key| hash[key] = [] }
    @ranked.each do |word|
      @by_length[word.length] << word
      word.each_char.with_index do |letter, position|
        @by_position[[word.length, position, letter]] << word
      end
    end
  end

  def candidates(pattern, minimum, used)
    pool = @by_length.fetch(pattern.length, [])
    known = []
    pattern.each_char.with_index do |letter, position|
      next if letter == '.'

      known << [position, letter]
      matching = @by_position.fetch([pattern.length, position, letter], [])
      pool = matching if matching.length < pool.length
    end
    result = []
    pool.each do |word|
      break if @scores.fetch(word) < minimum
      next if used.include?(word)
      next unless known.all? { |position, letter| word[position] == letter }

      result << word
    end
    result
  end
end
